<?php
namespace Modules\Ran\Http\Controllers;use Illuminate\Http\Request;use Modules\Ran\Entities\DocumentTemplate;use Modules\Ran\Services\TemplateService;
class TemplateController extends RanController{public function index(){return view('ran::templates.index',['templates'=>DocumentTemplate::query()->withCount('sections')->orderBy('document_type')->get()]);}public function edit(DocumentTemplate $template){return view('ran::templates.edit',['template'=>$template->load('sections')]);}public function update(Request $r,DocumentTemplate $template,TemplateService $service){$data=$r->validate(['name'=>'required|string|max:120','paper_size'=>'required|in:A4,A5,letter,58mm,80mm','orientation'=>'required|in:portrait,landscape','is_default'=>'nullable|boolean','is_active'=>'nullable|boolean','sections'=>'required|array','sections.*.title'=>'required|string|max:120','sections.*.sort_order'=>'required|integer|min:0','sections.*.enabled_by_default'=>'nullable|boolean','sections.*.allow_print'=>'nullable|boolean','sections.*.allow_sms'=>'nullable|boolean','sections.*.allow_email'=>'nullable|boolean','sections.*.allow_whatsapp'=>'nullable|boolean']);$service->update($template,$data);return back()->with('status','Document template updated.');}}
